def check_occurences(tuples_list):
    result = {}
    for t in tuples_list:
        # Ensure each tuple is in sorted order
        sorted_tuple = tuple(sorted(t))
        # Count occurrences
        if sorted_tuple in result:
            result[sorted_tuple] += 1
        else:
            result[sorted_tuple] = 1
    return result
