def merge_dictionaries_three(dict1, dict2, dict3):
    """
    Merge three dictionaries into one, ensuring the values from later dictionaries overwrite earlier ones.
    """
    # Initialize an empty dictionary for the result
    result = {}

    # Merge dictionaries in the order provided, later ones overwrite earlier ones
    for d in (dict1, dict2, dict3):
        result.update(d)

    return result

# Test cases to ensure the function works as intended
assert merge_dictionaries_three(
    { "R": "Red", "B": "Black", "P": "Pink" },
    { "G": "Green", "W": "White" },
    { "O": "Orange", "W": "White", "B": "Black" }
) == {'B': 'Black', 'R': 'Red', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'O': 'Orange'}

assert merge_dictionaries_three(
    { "R": "Red", "B": "Black", "P": "Pink" },
    { "G": "Green", "W": "White" },
    { "L": "lavender", "B": "Blue" }
) == {'R': 'Red', 'B': 'Blue', 'P': 'Pink', 'G': 'Green', 'W': 'White', 'L': 'lavender'}
